const names = [_][]const u8{ "Sato", "Suzuki", "Takahashi", "Tanaka", "Ito", "Watanabe" };
const usages = [_]u32{ 85, 120, 254, 300, 438, 176 };
var total: u32 = 0;
for (names, usages) |name, usage| {
    var bill: u32 = 900 + @as(u32, @min(usage, 120)) * 30;
    if (usage > 120)
        bill += @as(u32, @min(usage - 120, 180)) * 36;
    if (usage > 300)
        bill += (usage - 300) * 40;
    total += bill;
